actions.script:
const out = ec.service.sync().name('ironstone.commons.ContactServices.export#ContactFile').parameters({partyId: partyId, format: format || 'vcard'}).call()
if (!ec.message.hasError() && out?.location) ec.web.sendResourceResponse(out.location, false)
else ec.web.sendJsonResponse({})

const out = ec.service.sync().name('ironstone.commons.ContactServices.get#ContactAvatar').parameters({partyId: partyId}).call()
if (out?.contentLocation) ec.web.sendResourceResponse(out.contentLocation, true)
else ec.web.sendJsonError(404, ec.l10n.localize('No picture'))

const words = term ? String(term).trim() : ''
const out = []
if (words) {
    const base = {pageSize: 20, orderByField: 'firstName,organizationName'}
    if (organizationsOnly === 'Y') base.partyTypeEnumId = 'PtyOrganization'
    if (directoryOnly === 'Y') base.personalContacts = 'exclude'
    const params = Object.assign({anyField: words, leadingWildcard: words.includes('@')}, base)
    const found = ec.service.sync().name('mantle.party.PartyServices.find#Party').parameters(params).call()
    const ids = Array.from(found?.partyIdList || []).filter((id) => id !== excludePartyId)
    const rows = ec.service.sync().name('ironstone.commons.ContactServices.get#ContactRows').parameters({partyIdList: ids}).call()?.rowList || []
    for (const row of rows) out.push({value: row.partyId, label: row.name + (row.subtitle ? ' · ' + row.subtitle : '') +
        (row.emailAddress ? ' · ' + row.emailAddress : '') + (row.isPersonal ? ' · ' + ec.l10n.localize('personal') : '')})
}
ec.web.sendJsonResponse(out)

const books = ec.service.sync().name('mantle.party.ContactBookServices.get#UserContactBooks').call()?.contactBookList || []
const book = books.find((entry) => entry.contactBookId === contactBookId)
ec.web.sendJsonResponse(book ? (book.groupList || []).map((group) => ({value: group.contactBookGroupId, label: group.groupName})) : [])
